INSERT INTO `grammar_topics` (`id`, `lesson_id`, `title`, `rule_summary`, `formula`, `examples`) VALUES ('90909090-0000-0000-0000-000000000001', '50505050-0000-0000-0000-000000000001', 'Trends & Proportional Comparisons in Data Reporting', 'Sử dụng các động từ chỉ xu hướng (surge, plummet, fluctuate) kết hợp trạng từ (dramatically, moderately) và cấu trúc so sánh kép.', 'Subject + Verb of Trend + Adverb + from [X] to [Y] + in [Time]', 'Revenue surged dramatically from $2M to $8M in 2025. | The percentage dropped moderately.');
INSERT INTO `grammar_topics` (`id`, `lesson_id`, `title`, `rule_summary`, `formula`, `examples`) VALUES ('90909090-0000-0000-0000-000000000002', '50505050-0000-0000-0000-000000000005', 'Inversion with Negative Adverbials', 'Đảo ngữ để nhấn mạnh ý phủ định hoặc giới hạn (Not only, Rarely, Scarcely, Under no circumstances).', 'Negative Adverbial + Auxiliary Verb + Subject + Main Verb', 'Not only did the team refactor the codebase, but they also reduced latency by 40%.');
INSERT INTO `grammar_topics` (`id`, `lesson_id`, `title`, `rule_summary`, `formula`, `examples`) VALUES ('90909090-0000-0000-0000-000000000003', '50505050-0000-0000-0000-000000000007', 'Conditional Clauses in Contract Negotiations (Type 2 & Mixed)', 'Cấu trúc câu điều kiện loại 2 và hỗn hợp thể hiện điều khoản giả định hoặc nhượng bộ trong đàm phán hợp đồng thương mại.', 'If + S + past simple, S + would/could + base verb', 'If your team delivered the milestone ahead of schedule, we would consider a performance bonus.');
INSERT INTO `grammar_topics` (`id`, `lesson_id`, `title`, `rule_summary`, `formula`, `examples`) VALUES ('90909090-0000-0000-0000-000000000004', '50505050-0000-0000-0000-000000000013', 'Modal Verbs in Technical Code Reviews & Pair Programming', 'Dùng modal verbs (could, might, should) để đưa ra góp ý mềm mỏng, mang tính xây dựng khi review pull request.', 'We might want to + base verb | Could we consider + V-ing?', 'We might want to extract this helper into an idempotent utility class to avoid race conditions.');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000001', 'refactoring', '/riːˈfæk.tər.ɪŋ/', 'noun', 'Tái cấu trúc mã nguồn - cải thiện cấu trúc bên trong mà không thay đổi hành vi bên ngoài.', 'Continuous refactoring is essential to prevent architectural erosion in large microservices.', 'https://dictionary.cambridge.org/media/english/us_pron/r/ref/refac/refactoring.mp3', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=600', 'code restructuring, code clean-up, optimization', 'code deterioration, technical debt accumulation', '50505050-0000-0000-0000-000000000013');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000002', 'scalability', '/ˌskeɪ.ləˈbɪl.ə.ti/', 'noun', 'Khả năng mở rộng của hệ thống để xử lý lượng tải lớn hơn khi có thêm tài nguyên.', 'Horizontal scalability allows our cluster to absorb peak traffic without downtime.', 'https://dictionary.cambridge.org/media/english/us_pron/s/sca/scala/scalability.mp3', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=600', 'extensibility, capacity growth, elasticity', 'rigidity, bottleneck vulnerability', '50505050-0000-0000-0000-000000000013');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000003', 'concurrency', '/kənˈkʌr.ən.si/', 'noun', 'Tính đồng thời - khả năng thực thi nhiều tác vụ cùng một khoảng thời gian.', 'Handling high concurrency without thread deadlocks requires robust synchronization primitives.', 'https://dictionary.cambridge.org/media/english/us_pron/c/con/concu/concurrency.mp3', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=600', 'parallelism, simultaneous execution', 'sequential processing, single-threading', '50505050-0000-0000-0000-000000000013');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000004', 'asynchronous', '/eɪˈsɪŋ.krə.nəs/', 'adjective', 'Bất đồng bộ - không cần chờ đợi tác vụ hoàn tất mới thực hiện tác vụ tiếp theo.', 'We adopted an asynchronous message broker to decouple video encoding from API responses.', 'https://dictionary.cambridge.org/media/english/us_pron/a/asy/async/asynchronous.mp3', 'https://images.unsplash.com/photo-1504639725590-34d0984388bd?w=600', 'non-blocking, decoupled, event-driven', 'synchronous, blocking', '50505050-0000-0000-0000-000000000013');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000005', 'idempotent', '/ˌaɪ.dɛmˈpoʊ.tənt/', 'adjective', 'Bất biến khi lặp lại - thực thi nhiều lần cho ra kết quả giống hệt thực thi một lần.', 'HTTP PUT and DELETE operations must be strictly idempotent according to REST standards.', 'https://dictionary.cambridge.org/media/english/us_pron/i/ide/idemp/idempotent.mp3', 'https://images.unsplash.com/photo-1516116211227-bbc6790b8f04?w=600', 'repeatable, invariant, stable', 'side-effect prone, volatile', '50505050-0000-0000-0000-000000000013');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000006', 'throughput', '/ˈθruː.pʊt/', 'noun', 'Thông lượng - số lượng đơn vị công việc hoặc dữ liệu được xử lý trong một đơn vị thời gian.', 'Database indexing boosted query throughput by more than 300 percent.', 'https://dictionary.cambridge.org/media/english/us_pron/t/thr/throu/throughput.mp3', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=600', 'processing capacity, data rate, bandwidth', 'latency, lag, blockage', '50505050-0000-0000-0000-000000000014');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000007', 'orchestration', '/ˌɔː.kɪˈstreɪ.ʃən/', 'noun', 'Điều phối hệ thống - tự động hóa cấu hình, quản lý và điều phối các dịch vụ máy tính.', 'Kubernetes provides container orchestration to ensure self-healing and zero downtime.', 'https://dictionary.cambridge.org/media/english/us_pron/o/orc/orche/orchestration.mp3', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=600', 'coordination, automated management, integration', 'manual intervention, disorganization', '50505050-0000-0000-0000-000000000014');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000008', 'polymorphism', '/ˌpɒl.iˈmɔː.fɪ.zəm/', 'noun', 'Tính đa hình - khả năng một đối tượng có thể nhận nhiều hình thức khác nhau trong OOP.', 'Polymorphism allows our audio engine to treat different TTS providers interchangeably.', 'https://dictionary.cambridge.org/media/english/us_pron/p/pol/polym/polymorphism.mp3', 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=600', 'multiformity, variability', 'monomorphism, uniformity', '50505050-0000-0000-0000-000000000014');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000009', 'latency', '/ˈleɪ.tən.si/', 'noun', 'Độ trễ - khoảng thời gian trôi qua giữa nguyên nhân và kết quả của một thay đổi vật lý trong hệ thống.', 'The Edge CDN cache minimized network latency for international audio streaming.', 'https://dictionary.cambridge.org/media/english/us_pron/l/lat/laten/latency.mp3', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=600', 'delay, lag, transit time', 'instantaneity, immediate response', '50505050-0000-0000-0000-000000000015');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000000a', 'microservices', '/ˈmaɪ.kroʊˌsɜː.vɪ.sɪz/', 'noun', 'Kiến trúc vi dịch vụ - chia phần mềm thành các dịch vụ độc lập, nhỏ gọn kết nối qua API.', 'Migrating from a monolith to microservices enhanced deployment velocity across teams.', 'https://dictionary.cambridge.org/media/english/us_pron/m/mic/micro/microservices.mp3', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=600', 'distributed architecture, decoupled services', 'monolithic architecture', '50505050-0000-0000-0000-000000000015');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000000b', 'deprecate', '/ˈdep.rə.keɪt/', 'verb', 'Không khuyến nghị sử dụng - đánh dấu tính năng cũ sắp bị loại bỏ trong các phiên bản sau.', 'We will deprecate the legacy REST endpoint in favor of the high-throughput WebSocket channel.', 'https://dictionary.cambridge.org/media/english/us_pron/d/dep/depre/deprecate.mp3', 'https://images.unsplash.com/photo-1584438784894-089d6a62b8fa?w=600', 'phase out, obsolete, decommission', 'endorse, introduce, support', '50505050-0000-0000-0000-000000000015');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000000c', 'negotiate', '/nəˈɡoʊ.ʃi.eɪt/', 'verb', 'Đàm phán, thương lượng để đạt được thỏa thuận đôi bên cùng có lợi.', 'Both executives met to negotiate the final licensing terms of the joint venture.', 'https://dictionary.cambridge.org/media/english/us_pron/n/neg/negot/negotiate.mp3', 'https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=600', 'bargain, deliberate, confer', 'dictate, impose', '50505050-0000-0000-0000-000000000007');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000000d', 'consensus', '/kənˈsen.səs/', 'noun', 'Sự đồng thuận chung giữa các thành viên trong tập thể.', 'After three hours of debate, the board reached a unanimous consensus on the expansion plan.', 'https://dictionary.cambridge.org/media/english/us_pron/c/con/conse/consensus.mp3', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=600', 'agreement, harmony, accord', 'dissent, disagreement, conflict', '50505050-0000-0000-0000-000000000007');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000000e', 'stakeholder', '/ˈsteɪkˌhoʊl.dər/', 'noun', 'Bên liên quan - cá nhân hoặc tổ chức có quyền lợi gắn liền với dự án.', 'Every project milestone was communicated transparently to primary stakeholders.', 'https://dictionary.cambridge.org/media/english/us_pron/s/sta/stake/stakeholder.mp3', 'https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=600', 'interested party, shareholder, partner', 'uninterested party', '50505050-0000-0000-0000-000000000007');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000000f', 'feasibility', '/ˌfiː.zəˈbɪl.ə.ti/', 'noun', 'Tính khả thi - khả năng thực hiện thành công của một ý tưởng hay kế hoạch.', 'A feasibility study revealed that cloud migration would save thirty percent of operational costs.', 'https://dictionary.cambridge.org/media/english/us_pron/f/fea/feasi/feasibility.mp3', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=600', 'viability, practicability, workability', 'impossibility, impracticability', '50505050-0000-0000-0000-000000000008');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000010', 'synergy', '/ˈsɪn.ɚ.dʒi/', 'noun', 'Sức mạnh hiệp đồng - hiệu quả gia tăng khi kết hợp nhiều bên lại với nhau.', 'The merger produced great synergy, expanding product lines while streamlining operations.', 'https://dictionary.cambridge.org/media/english/us_pron/s/syn/syner/synergy.mp3', 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=600', 'collaboration, mutual support, symbiosis', 'antagonism, counter-productivity', '50505050-0000-0000-0000-000000000008');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000011', 'benchmark', '/ˈbentʃ.mɑːrk/', 'noun', 'Tiêu chuẩn đối sánh - chuẩn mực dùng để đo lường và so sánh chất lượng.', 'The company set a new industry benchmark for customer retention and service reliability.', 'https://dictionary.cambridge.org/media/english/us_pron/b/ben/bench/benchmark.mp3', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600', 'standard, criterion, reference point', 'anomaly, outlier', '50505050-0000-0000-0000-000000000008');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000012', 'deliverable', '/dɪˈlɪv.ɚ.ə.bəl/', 'noun', 'Sản phẩm bàn giao - kết quả cụ thể phải hoàn thành theo cam kết hợp đồng.', 'The architectural design document is the first major deliverable due next Friday.', 'https://dictionary.cambridge.org/media/english/us_pron/d/del/deliv/deliverable.mp3', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=600', 'output, product, commitment', 'input, requirement', '50505050-0000-0000-0000-000000000009');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000013', 'milestone', '/ˈmaɪl.stoʊn/', 'noun', 'Cột mốc quan trọng trong quá trình thực hiện một dự án hoặc sự nghiệp.', 'Reaching 10,000 active learners was a celebratory milestone for the entire engineering staff.', 'https://dictionary.cambridge.org/media/english/us_pron/m/mil/miles/milestone.mp3', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?w=600', 'turning point, landmark, breakthrough', 'stagnation', '50505050-0000-0000-0000-000000000009');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000014', 'leverage', '/ˈlev.ɚ.ɪdʒ/', 'verb', 'Tận dụng tối đa - khai thác triệt để lợi thế hoặc tài nguyên có sẵn.', 'We must leverage modern generative AI models to automate personalized pronunciation coaching.', 'https://dictionary.cambridge.org/media/english/us_pron/l/lev/lever/leverage.mp3', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=600', 'utilize, capitalize on, exploit', 'squander, neglect', '50505050-0000-0000-0000-000000000009');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000015', 'contingency', '/kənˈtɪn.dʒən.si/', 'noun', 'Phương án dự phòng - sự kiện bất ngờ trong tương lai cần được chuẩn bị trước.', 'Our deployment plan includes a failover contingency in case the primary region goes offline.', 'https://dictionary.cambridge.org/media/english/us_pron/c/con/conti/contingency.mp3', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?w=600', 'backup plan, emergency reserve, safeguard', 'certainty, inevitability', '50505050-0000-0000-0000-00000000000a');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000016', 'lucrative', '/ˈluː.krə.tɪv/', 'adjective', 'Sinh lời lớn, mang lại lợi nhuận cao.', 'Securing enterprise training contracts proved to be a highly lucrative revenue channel.', 'https://dictionary.cambridge.org/media/english/us_pron/l/luc/lucra/lucrative.mp3', 'https://images.unsplash.com/photo-1579621970563-ebec7560ff3e?w=600', 'profitable, remunerative, gainful', 'unprofitable, loss-making', '50505050-0000-0000-0000-00000000000a');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000017', 'itinerary', '/aɪˈtɪn.ə.rer.i/', 'noun', 'Lịch trình chuyến đi - bản ghi chi tiết các điểm đến, thời gian và hoạt động.', 'The travel guide drafted a comprehensive 10-day itinerary exploring ancient heritage sites.', 'https://dictionary.cambridge.org/media/english/us_pron/i/iti/itine/itinerary.mp3', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?w=600', 'travel schedule, route, timetable', 'spontaneous wandering', '50505050-0000-0000-0000-00000000000d');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000018', 'breathtaking', '/ˈbreθˌteɪ.kɪŋ/', 'adjective', 'Ngoạn mục, đẹp đến nghẹt thở.', 'From the mountain peak, visitors were captivated by a breathtaking panoramic sunrise.', 'https://dictionary.cambridge.org/media/english/us_pron/b/bre/breat/breathtaking.mp3', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=600', 'stunning, magnificent, awe-inspiring', 'mundane, mediocre, uninspiring', '50505050-0000-0000-0000-00000000000d');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000019', 'hospitality', '/ˌhɑː.spɪˈtæl.ə.ti/', 'noun', 'Lòng hiếu khách - sự tiếp đón nồng hậu, thân thiện dành cho du khách.', 'The village locals welcomed the foreign travelers with warmth and exceptional hospitality.', 'https://dictionary.cambridge.org/media/english/us_pron/h/hos/hospi/hospitality.mp3', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=600', 'welcomeness, friendliness, generosity', 'hostility, unfriendliness', '50505050-0000-0000-0000-00000000000d');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000001a', 'excursion', '/ɪkˈskɝː.ʒən/', 'noun', 'Chuyến du ngoạn ngắn ngày nhằm mục đích thư giãn hoặc khám phá.', 'We booked a weekend excursion to explore the coral reefs and limestone caves.', 'https://dictionary.cambridge.org/media/english/us_pron/e/exc/excur/excursion.mp3', 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?w=600', 'short trip, jaunt, outing', 'permanent stay', '50505050-0000-0000-0000-00000000000e');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000001b', 'picturesque', '/ˌpɪk.tʃərˈesk/', 'adjective', 'Đẹp như tranh vẽ - có vẻ đẹp cổ kính, mộc mạc và thu hút ánh nhìn.', 'The picturesque coastal town attracted photographers and painters from across Europe.', 'https://dictionary.cambridge.org/media/english/us_pron/p/pic/pictu/picturesque.mp3', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=600', 'scenic, charming, attractive', 'ugly, dreary, unsightly', '50505050-0000-0000-0000-00000000000e');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000001c', 'cosmopolitan', '/ˌkɑːz.məˈpɑː.lɪ.tən/', 'adjective', 'Mang tầm quốc tế, đa văn hóa - quy tụ người từ nhiều quốc gia và sắc tộc.', 'Singapore is renowned for its cosmopolitan atmosphere and vibrant multicultural cuisine.', 'https://dictionary.cambridge.org/media/english/us_pron/c/cos/cosmo/cosmopolitan.mp3', 'https://images.unsplash.com/photo-1477959858617-67f30bc75b82?w=600', 'multicultural, worldly, international', 'insular, provincial, parochial', '50505050-0000-0000-0000-00000000000e');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000001d', 'heritage', '/ˈher.ɪ.tɪdʒ/', 'noun', 'Di sản văn hóa hoặc lịch sử truyền thống được lưu giữ qua nhiều thế hệ.', 'Preserving architectural heritage while fostering modern urban growth is a delicate balance.', 'https://dictionary.cambridge.org/media/english/us_pron/h/her/herit/heritage.mp3', 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=600', 'legacy, tradition, cultural inheritance', 'novelty, modernism', '50505050-0000-0000-0000-00000000000f');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000001e', 'indigenous', '/ɪnˈdɪdʒ.ə.nəs/', 'adjective', 'Bản địa, thuộc về địa phương từ nguồn gốc ban đầu.', 'Ecotourism initiatives help protect the rights and customs of indigenous communities.', 'https://dictionary.cambridge.org/media/english/us_pron/i/ind/indig/indigenous.mp3', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=600', 'native, aboriginal, endemic', 'exotic, foreign, invasive', '50505050-0000-0000-0000-00000000000f');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000001f', 'culinary', '/ˈkʌl.ə.ner.i/', 'adjective', 'Thuộc về ẩm thực, nghệ thuật nấu nướng và thưởng thức món ăn.', 'The culinary tour introduced guests to authentic street flavors and secret family recipes.', 'https://dictionary.cambridge.org/media/english/us_pron/c/cul/culin/culinary.mp3', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=600', 'gastronomic, cooking, epicurean', 'inedible', '50505050-0000-0000-0000-00000000000f');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000020', 'wanderlust', '/ˈwɑːn.dɚ.lʌst/', 'noun', 'Niềm khao khát du hành khám phá thế giới mãnh liệt.', 'Her insatiable wanderlust drove her to visit over fifty countries in less than six years.', 'https://dictionary.cambridge.org/media/english/us_pron/w/wan/wande/wanderlust.mp3', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=600', 'itchy feet, love of travel, restless desire to wander', 'stay-at-home nature', '50505050-0000-0000-0000-000000000010');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000021', 'tranquility', '/træŋˈkwɪl.ə.ti/', 'noun', 'Sự thanh bình, tĩnh lặng tuyệt đối.', 'The remote island offered pure tranquility away from the noisy congestion of metropolitan life.', 'https://dictionary.cambridge.org/media/english/us_pron/t/tra/trang/tranquility.mp3', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600', 'serenity, calmness, peace', 'turmoil, chaos, commotion', '50505050-0000-0000-0000-000000000010');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000022', 'ubiquitous', '/juːˈbɪk.wə.təs/', 'adjective', 'Phổ biến khắp nơi, có mặt ở mọi chỗ.', 'Smartphones have become ubiquitous in contemporary society, altering social communication.', 'https://dictionary.cambridge.org/media/english/us_pron/u/ubi/ubiqu/ubiquitous.mp3', 'https://images.unsplash.com/photo-1512499617640-c74ae3a79d37?w=600', 'omnipresent, pervasive, everywhere', 'rare, scarce, isolated', '50505050-0000-0000-0000-000000000001');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000023', 'ameliorate', '/əˈmiːl.jə.reɪt/', 'verb', 'Cải thiện, làm cho một tình huống tiêu cực trở nên tốt hơn.', 'Targeted policy interventions can ameliorate poverty and enhance public educational access.', 'https://dictionary.cambridge.org/media/english/us_pron/a/ame/ameli/ameliorate.mp3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=600', 'improve, mitigate, relieve', 'exacerbate, worsen, aggravate', '50505050-0000-0000-0000-000000000001');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000024', 'paradigm', '/ˈper.ə.daɪm/', 'noun', 'Hình mẫu, mô thức tư duy hoặc hệ hình chuẩn mực.', 'The sudden shift towards remote learning created a new paradigm in higher education pedagogy.', 'https://dictionary.cambridge.org/media/english/us_pron/p/par/parad/paradigm.mp3', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=600', 'model, standard, conceptual framework', 'aberration', '50505050-0000-0000-0000-000000000001');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000025', 'discrepancy', '/dɪˈskrep.ən.si/', 'noun', 'Sự sai biệt, không nhất quán giữa hai hoặc nhiều nguồn dữ liệu.', 'The auditor highlighted a notable discrepancy between the reported revenue and actual bank deposits.', 'https://dictionary.cambridge.org/media/english/us_pron/d/dis/discr/discrepancy.mp3', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?w=600', 'inconsistency, variance, disparity', 'correspondence, alignment, congruity', '50505050-0000-0000-0000-000000000002');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000026', 'substantiate', '/səbˈstæn.ʃi.eɪt/', 'verb', 'Chứng minh, cung cấp bằng chứng xác thực cho một luận điểm.', 'The candidate failed to substantiate her academic claims with peer-reviewed publications.', 'https://dictionary.cambridge.org/media/english/us_pron/s/sub/subst/substantiate.mp3', 'https://images.unsplash.com/photo-1455849318743-b2233052fcff?w=600', 'validate, prove, authenticate', 'refute, disprove, undermine', '50505050-0000-0000-0000-000000000002');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000027', 'proliferation', '/prəˌlɪf.əˈreɪ.ʃən/', 'noun', 'Sự sinh sôi, gia tăng nhanh chóng về số lượng.', 'The proliferation of generative language tools is transforming traditional assessment methods.', 'https://dictionary.cambridge.org/media/english/us_pron/p/pro/proli/proliferation.mp3', 'https://images.unsplash.com/photo-1507668077129-56e32842fceb?w=600', 'multiplication, rapid growth, surge', 'diminution, decline, reduction', '50505050-0000-0000-0000-000000000002');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000028', 'deleterious', '/ˌdel.ɪˈtɪr.i.əs/', 'adjective', 'Có hại, gây tổn hại nghiêm trọng.', 'Chronic sleep deprivation can exert deleterious effects on cognitive focus and emotional stamina.', 'https://dictionary.cambridge.org/media/english/us_pron/d/del/delet/deleterious.mp3', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=600', 'harmful, detrimental, injurious', 'beneficial, advantageous, wholesome', '50505050-0000-0000-0000-000000000003');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-000000000029', 'inevitable', '/ɪnˈev.ə.t̬ə.bəl/', 'adjective', 'Không thể tránh khỏi, chắc chắn sẽ xảy ra.', 'Technological disruption is an inevitable consequence of competitive global markets.', 'https://dictionary.cambridge.org/media/english/us_pron/i/ine/inevi/inevitable.mp3', 'https://images.unsplash.com/photo-1499750310107-5fef28a66643?w=600', 'unavoidable, inescapable, fated', 'preventable, avoidable', '50505050-0000-0000-0000-000000000003');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000002a', 'comprehensive', '/ˌkɑːm.prəˈhen.sɪv/', 'adjective', 'Toàn diện, bao quát mọi khía cạnh.', 'The curriculum provides comprehensive coverage of listening, speaking, reading and writing.', 'https://dictionary.cambridge.org/media/english/us_pron/c/com/compr/comprehensive.mp3', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=600', 'all-inclusive, thorough, exhaustive', 'partial, superficial, incomplete', '50505050-0000-0000-0000-000000000003');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000002b', 'counterproductive', '/ˌkaʊn.t̬ɚ.prəˈdʌk.tɪv/', 'adjective', 'Phản tác dụng - dẫn đến kết quả ngược lại với mục tiêu ban đầu.', 'Imposing excessively harsh deadlines often proves counterproductive to software code quality.', 'https://dictionary.cambridge.org/media/english/us_pron/c/cou/count/counterproductive.mp3', 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=600', 'detrimental, self-defeating, adverse', 'productive, fruitful, helpful', '50505050-0000-0000-0000-000000000004');
INSERT INTO `vocabulary_items` (`id`, `word`, `ipa`, `part_of_speech`, `meaning`, `example_sentence`, `audio_url`, `image_url`, `synonyms`, `antonyms`, `lesson_id`) VALUES ('a0a0a0a0-0000-0000-0000-00000000002c', 'lucid', '/ˈluː.sɪd/', 'adjective', 'Rõ ràng, minh bạch, dễ hiểu và khúc chiết.', 'The lecturer gave a lucid explanation of complex quantum mechanics principles.', 'https://dictionary.cambridge.org/media/english/us_pron/l/luc/lucid/lucid.mp3', 'https://images.unsplash.com/photo-1499750310107-5fef28a66643?w=600', 'clear, coherent, articulate', 'vague, obscure, confusing', '50505050-0000-0000-0000-000000000004');
