INSERT INTO `assignments` (`id`, `class_id`, `lesson_id`, `title`, `description`, `skill_type`, `time_limit_minutes`, `max_attempts`, `pass_score`, `due_date`, `audio_url`, `listening_script`, `created_at`, `updated_at`) VALUES ('c0c0c0c0-0000-0000-0000-000000000003', '44444444-4444-4444-4444-000000000001', '50505050-0000-0000-0000-000000000003', 'IELTS Listening CBT: Academic University Research Symposium', 'Nguồn: TTS_GENERATED | Nghe đoạn hội thoại giữa giáo sư và sinh viên về dự án nghiên cứu AI trong y tế và làm bài trắc nghiệm CBT.', 'LISTENING', 30, 2, 7, '2026-11-20 23:59:59.000000', NULL, 'Professor: Welcome everyone to our weekly symposium. Today David will outline his methodology on acoustic formant analysis in language acquisition.', '2026-10-20 08:00:00.000000', '2026-10-20 08:00:00.000000');
