INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000001', 'c0c0c0c0-0000-0000-0000-000000000001', 1, 'ESSAY', 'The chart illustrates renewable energy capacity (GW) across solar, wind, and hydro between 2010 and 2025. Summarize the information by selecting and reporting the main features, and make comparisons where relevant (at least 150 words).', 'Sample high-band essay comparing solar surge against steady hydroelectric output.', 'Tiêu chí chấm: Task Achievement (đủ số từ, chọn đúng xu hướng chính), Coherence (từ nối, phân đoạn hợp lý), Lexical (từ vựng dữ liệu), Grammar (cấu trúc câu đa dạng).', 10, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000002', 'c0c0c0c0-0000-0000-0000-000000000002', 1, 'AUDIO_RESPONSE', 'Describe an innovative tech product or application you use daily. You should say: what it is, how often you use it, what features it has, and explain why it is essential to your productivity.', 'Describe an innovative tech product or application you use daily. You should say: what it is, how often you use it, what features it has, and explain why it is essential to your productivity.', 'Chấm điểm AI SpeechSuper / Groq Whisper 4 tiêu chí theo band điểm IELTS Speaking.', 10, NULL, 'Describe an innovative tech product or application you use daily. You should say: what it is, how often you use it, what features it has, and explain why it is essential to your productivity.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000003', 'c0c0c0c0-0000-0000-0000-000000000003', 1, 'MULTIPLE_CHOICE', 'What is the primary objective of David''s symposium presentation?', 'A', 'Giải thích: Trong bài nghe, David nhấn mạnh mục tiêu nghiên cứu là đo lường formants âm vị trong việc tiếp thu ngôn ngữ thứ hai.', 2.5, NULL, 'David: The core intent of our study is evaluating vowel formant shifts among bilingual participants.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000004', 'c0c0c0c0-0000-0000-0000-000000000003', 2, 'MULTIPLE_CHOICE', 'Which demographic cohort participated in the experimental trial?', 'C', 'Giải thích: Thí nghiệm được thực hiện trên nhóm sinh viên kỹ thuật đa quốc gia từ 20 đến 25 tuổi.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000005', 'c0c0c0c0-0000-0000-0000-000000000003', 3, 'MULTIPLE_CHOICE', 'What acoustic metric showed the most significant statistical improvement?', 'B', 'Giải thích: Chỉ số F1/F2 frequency ratio cải thiện 34% sau 4 tuần luyện tập Shadowing.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000006', 'c0c0c0c0-0000-0000-0000-000000000003', 4, 'MULTIPLE_CHOICE', 'What will the research team investigate in their subsequent phase?', 'D', 'Giải thích: Giai đoạn tiếp theo tập trung vào ngữ điệu câu (pitch contour) và giảm thiểu tạp âm môi trường.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000007', 'c0c0c0c0-0000-0000-0000-000000000004', 1, 'TRUE_FALSE', 'Autonomous robotics adoption in logistics expanded by over 200% between 2020 and 2024.', 'TRUE', 'Giải thích: Đoạn văn thứ 2 nêu rõ: "Logistical fulfillment centers experienced a 215% surge in autonomous vehicle deployment from 2020 to 2024."', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000008', 'c0c0c0c0-0000-0000-0000-000000000004', 2, 'TRUE_FALSE', 'Safety regulations prohibited all human-robot collaboration on assembly lines.', 'FALSE', 'Giải thích: Bài viết khẳng định các tiêu chuẩn an toàn ISO tạo điều kiện cho cobots làm việc sát cánh cùng con người.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000009', 'c0c0c0c0-0000-0000-0000-000000000004', 3, 'TRUE_FALSE', 'The majority of warehouse robots were manufactured exclusively in Germany.', 'NOT_GIVEN', 'Giải thích: Bài viết không đề cập đến tỷ lệ sản xuất theo quốc gia cụ thể.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000000a', 'c0c0c0c0-0000-0000-0000-000000000004', 4, 'FILL_IN_BLANK', 'The deployment of predictive maintenance sensors reduced unexpected factory [downtime] by forty percent.', 'downtime', 'Giải thích: Từ cần điền là "downtime" (thời gian chết của máy móc).', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000000b', 'c0c0c0c0-0000-0000-0000-000000000005', 1, 'MULTIPLE_CHOICE', 'Where does this conversation most likely take place?', 'B', 'Giải thích: Từ khóa "quarterly profit report", "shareholder meeting" cho biết bối cảnh tại văn phòng công ty.', 3.3, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000000c', 'c0c0c0c0-0000-0000-0000-000000000005', 2, 'MULTIPLE_CHOICE', 'What contributed most to the recent profit surge?', 'A', 'Giải thích: Người phụ nữ nói rõ: "largely due to our cloud service expansion".', 3.3, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000000d', 'c0c0c0c0-0000-0000-0000-000000000005', 3, 'MULTIPLE_CHOICE', 'What does the man suggest doing next Tuesday?', 'C', 'Giải thích: Người đàn ông đề xuất: "Let us schedule a briefing with the enterprise sales representatives next Tuesday."', 3.4, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000000e', 'c0c0c0c0-0000-0000-0000-000000000006', 1, 'MULTIPLE_CHOICE', 'Ms. Jenkins was selected to lead the negotiation team because of her _______ expertise in international trade contracts.', 'C', 'Giải thích: Cần một tính từ bổ nghĩa cho "expertise". "Comprehensive" (toàn diện, sâu rộng) là từ chính xác nhất.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000000f', 'c0c0c0c0-0000-0000-0000-000000000006', 2, 'MULTIPLE_CHOICE', 'Neither the design engineers _______ the project manager anticipated the database failover during the load test.', 'B', 'Giải thích: Cấu trúc tương liên: Neither ... nor ...', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000010', 'c0c0c0c0-0000-0000-0000-000000000006', 3, 'MULTIPLE_CHOICE', 'The updated server firmware will be deployed _______ midnight to minimize user interruption.', 'A', 'Giải thích: Giới từ chỉ thời điểm cụ thể: "at midnight".', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000011', 'c0c0c0c0-0000-0000-0000-000000000006', 4, 'MULTIPLE_CHOICE', 'All travel expense claims must be submitted to accounting _______ ten business days of return.', 'D', 'Giải thích: Giới từ chỉ khoảng thời gian: "within ten business days".', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000012', 'c0c0c0c0-0000-0000-0000-000000000008', 1, 'AUDIO_RESPONSE', 'Listen and shadow the sentence: "Continuous practice empowers learners to speak with unwavering confidence."', 'Continuous practice empowers learners to speak with unwavering confidence.', 'Luyện nhịp điệu trọng âm từ (rhythm and cadence).', 3.4, NULL, 'Continuous practice empowers learners to speak with unwavering confidence.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000013', 'c0c0c0c0-0000-0000-0000-000000000008', 2, 'AUDIO_RESPONSE', 'Listen and shadow the sentence: "Accurate pronunciation requires conscious tongue positioning and breath support."', 'Accurate pronunciation requires conscious tongue positioning and breath support.', 'Luyện phụ âm /r/, /ʃ/ và âm đuôi /s/, /t/.', 3.3, NULL, 'Accurate pronunciation requires conscious tongue positioning and breath support.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000014', 'c0c0c0c0-0000-0000-0000-000000000008', 3, 'AUDIO_RESPONSE', 'Listen and shadow the sentence: "Clear articulation and steady rhythm help speakers communicate complex ideas effectively."', 'Clear articulation and steady rhythm help speakers communicate complex ideas effectively.', 'Luyện phát âm nguyên âm đôi và ngữ điệu kết câu tự nhiên.', 3.3, NULL, 'Clear articulation and steady rhythm help speakers communicate complex ideas effectively.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000015', 'c0c0c0c0-0000-0000-0000-000000000009', 1, 'AUDIO_RESPONSE', 'Shadow Steve Jobs: "You can not connect the dots looking forward; you can only connect them looking backward."', 'You can not connect the dots looking forward; you can only connect them looking backward.', 'Luyện nối âm (linking) "dots looking" và nuốt âm (elision).', 5, NULL, 'You can not connect the dots looking forward; you can only connect them looking backward.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000016', 'c0c0c0c0-0000-0000-0000-000000000009', 2, 'AUDIO_RESPONSE', 'Shadow Steve Jobs: "Stay hungry, stay foolish."', 'Stay hungry, stay foolish.', 'Luyện ngữ điệu cảm xúc lắng đọng và độ ngân âm.', 5, NULL, 'Stay hungry, stay foolish.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000017', 'c0c0c0c0-0000-0000-0000-00000000000a', 1, 'FILL_IN_BLANK', 'Listen to the audio clip and type the missing word: "What are you [going to] do about the project timeline?"', 'going to', 'Người nói phát âm lướt "gonna" nhưng trong văn bản chuẩn cần gõ "going to".', 3.3, NULL, 'What are you going to do about the project timeline?');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000018', 'c0c0c0c0-0000-0000-0000-00000000000a', 2, 'FILL_IN_BLANK', 'Type the missing word: "The lead architect suggested [refactoring] the authentication service."', 'refactoring', 'Từ vựng kỹ thuật: refactoring (tái cấu trúc code).', 3.3, NULL, 'The lead architect suggested refactoring the authentication service.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000019', 'c0c0c0c0-0000-0000-0000-00000000000a', 3, 'FILL_IN_BLANK', 'Type the missing word: "We observed a significant decrease in system [latency] after caching."', 'latency', 'Từ vựng: latency (độ trễ hệ thống).', 3.4, NULL, 'We observed a significant decrease in system latency after caching.');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000001a', 'c0c0c0c0-0000-0000-0000-00000000000b', 1, 'ESSAY', 'Record or write your Daily Standup update (approx. 80-120 words). Cover: (1) What you achieved yesterday, (2) What you plan to achieve today, and (3) Any technical blockers in your pipeline.', 'Yesterday I resolved the JWT token refresh timeout in the auth filter. Today I am optimizing database indexing for vocabulary queries. No blockers at this time.', 'Chấm điểm tính rõ ràng, từ vựng kỹ thuật (Scrum Agile, backend terms) và sự súc tích.', 10, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000001b', 'c0c0c0c0-0000-0000-0000-00000000000d', 1, 'MATCHING', 'Match the vocabulary term to its correct definition: [refactoring]', 'Improving internal code structure without changing external behavior', 'Refactoring là tái cấu trúc code mà giữ nguyên hành vi bên ngoài.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000001c', 'c0c0c0c0-0000-0000-0000-00000000000d', 2, 'MATCHING', 'Match the vocabulary term to its correct definition: [scalability]', 'Ability of a system to handle growing workloads by adding resources', 'Scalability là khả năng mở rộng của hệ thống.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000001d', 'c0c0c0c0-0000-0000-0000-00000000000d', 3, 'MATCHING', 'Match the vocabulary term to its correct definition: [idempotent]', 'An operation producing the same result regardless of execution count', 'Idempotent là tính bất biến khi thực thi nhiều lần.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000001e', 'c0c0c0c0-0000-0000-0000-00000000000d', 4, 'MATCHING', 'Match the vocabulary term to its correct definition: [asynchronous]', 'Execution that does not block waiting for a task to finish', 'Asynchronous là thực thi bất đồng bộ, non-blocking.', 2.5, NULL, NULL);
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-00000000001f', 'c0c0c0c0-0000-0000-0000-00000000000e', 1, 'MULTIPLE_CHOICE', 'Listen to the audio and select the word spoken: price or prize?', 'A', 'Giải thích: Âm cuối là vô thanh /s/ (price), không phải hữu thanh /z/ (prize).', 3.3, NULL, 'price');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000020', 'c0c0c0c0-0000-0000-0000-00000000000e', 2, 'MULTIPLE_CHOICE', 'Listen to the audio and select the word spoken: sheep or ship?', 'B', 'Giải thích: Âm nguyên âm ngắn /ɪ/ trong "ship", đối lập với nguyên âm dài /iː/ trong "sheep".', 3.3, NULL, 'ship');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000021', 'c0c0c0c0-0000-0000-0000-00000000000e', 3, 'MULTIPLE_CHOICE', 'Listen to the audio and select the word spoken: bad or bed?', 'A', 'Giải thích: Âm /æ/ hạ hàm sâu trong "bad", đối lập với /e/ trong "bed".', 3.4, NULL, 'bad');
INSERT INTO `assignment_questions` (`id`, `assignment_id`, `order_index`, `question_type`, `prompt_text`, `correct_answer`, `explanation`, `points`, `media_url`, `transcript`) VALUES ('d0d0d0d0-0000-0000-0000-000000000022', 'c0c0c0c0-0000-0000-0000-00000000000f', 1, 'FILL_IN_BLANK', 'Type the complete sentence heard: "[The chief executive officer confirmed that customer retention improved by twelve percent this quarter.]"', 'The chief executive officer confirmed that customer retention improved by twelve percent this quarter.', 'Chú ý viết hoa đầu câu, số phần trăm "twelve percent" và dấu chấm câu.', 5, NULL, 'The chief executive officer confirmed that customer retention improved by twelve percent this quarter.');
