INSERT INTO `student_answers` (`id`, `attempt_id`, `question_id`, `text_response`, `audio_response_url`, `is_correct`, `earned_points`, `eval_feedback`) VALUES ('06060606-0000-0000-0000-000000000001', '05050505-0000-0000-0000-000000000001', 'd0d0d0d0-0000-0000-0000-000000000001', 'The provided line graph illustrates the consumption of renewable energy in gigawatts across solar, wind, and hydroelectric sources between 2010 and 2025. Overall, solar energy experienced the most pronounced growth over the fifteen-year period, whereas hydroelectric power remained relatively plateaued. In 2010, hydroelectric was the dominant sector, generating approximately 35 GW, compared to merely 5 GW for solar and 12 GW for wind. However, after 2015, solar energy accelerated dramatically, overtaking wind by 2018 and reaching an unprecedented peak of 85 GW by 2025. Conversely, hydroelectricity fluctuated marginally before settling at 42 GW. In summary, renewable investments shifted substantially towards photovoltaic technology.', NULL, 1, 8.2, 'Phân tích số liệu sắc bén, vốn từ học thuật phong phú.');
INSERT INTO `student_answers` (`id`, `attempt_id`, `question_id`, `text_response`, `audio_response_url`, `is_correct`, `earned_points`, `eval_feedback`) VALUES ('06060606-0000-0000-0000-000000000002', '05050505-0000-0000-0000-000000000002', 'd0d0d0d0-0000-0000-0000-000000000002', 'Today I would like to speak about an AI-powered code assistant that has radically transformed my development routine.', NULL, 1, 8.6, 'Phát âm chuẩn xác, ngữ điệu tự nhiên, từ nối mạch lạc.');
INSERT INTO `student_answers` (`id`, `attempt_id`, `question_id`, `text_response`, `audio_response_url`, `is_correct`, `earned_points`, `eval_feedback`) VALUES ('06060606-0000-0000-0000-000000000003', '05050505-0000-0000-0000-000000000003', 'd0d0d0d0-0000-0000-0000-00000000000c', 'Continuous practice empowers learners to speak with unwavering confidence.', NULL, 1, 3.2, 'Nhịp điệu câu và trọng âm từ rất tự nhiên.');
INSERT INTO `student_answers` (`id`, `attempt_id`, `question_id`, `text_response`, `audio_response_url`, `is_correct`, `earned_points`, `eval_feedback`) VALUES ('06060606-0000-0000-0000-000000000004', '05050505-0000-0000-0000-000000000003', 'd0d0d0d0-0000-0000-0000-00000000000d', 'Accurate pronunciation requires conscious tongue positioning and breath support.', NULL, 1, 3, 'Phát âm phụ âm /r/ và /ʃ/ rất rõ ràng.');
INSERT INTO `student_answers` (`id`, `attempt_id`, `question_id`, `text_response`, `audio_response_url`, `is_correct`, `earned_points`, `eval_feedback`) VALUES ('06060606-0000-0000-0000-000000000005', '05050505-0000-0000-0000-000000000003', 'd0d0d0d0-0000-0000-0000-00000000000e', 'Clear articulation and steady rhythm help speakers communicate complex ideas effectively.', NULL, 1, 3, 'Bắt chước cao độ và tốc độ rất mượt mà.');
