INSERT INTO `ai_evaluations` (`id`, `student_answer_id`, `eval_type`, `overall_score`, `pronunciation_score`, `fluency_score`, `grammar_score`, `vocabulary_score`, `coherence_score`, `estimated_cefr`, `evaluation_engine`, `tokens_used`, `stt_transcript`, `corrected_text`, `mistakes_json`, `suggestions_json`, `created_at`) VALUES ('07070707-0000-0000-0000-000000000001', '06060606-0000-0000-0000-000000000001', 'WRITING', 82, NULL, NULL, 80, 85, 81, 'B2', 'TIER_2_GROQ_LLAMA', 1240, NULL, 'The provided line graph illustrates the consumption of renewable energy in gigawatts across solar, wind, and hydroelectric sources between 2010 and 2025. Overall, solar energy experienced the most pronounced growth over the fifteen-year period, whereas hydroelectric power remained relatively plateaued. In 2010, hydroelectric was the dominant sector, generating approximately 35 GW, compared to merely 5 GW for solar and 12 GW for wind. However, after 2015, solar energy accelerated dramatically, overtaking wind by 2018 and reaching an unprecedented peak of 85 GW by 2025. Conversely, hydroelectricity fluctuated marginally before settling at 42 GW. In summary, renewable investments shifted substantially towards photovoltaic technology.', '[{"line":2,"original":"remained relatively plateaued","correction":"plateaued relatively early / remained relatively stable","type":"Collocation","explanationVi":"Cụm ''remained plateaued'' hơi lặp từ, nên dùng ''remained relatively stable'' hoặc ''plateaued in the second half''."},{"line":4,"original":"accelerated dramatically","correction":"accelerated dramatically (Good Academic Usage)","type":"Style Praise","explanationVi":"Cách phối hợp động từ ''accelerate'' và trạng từ ''dramatically'' rất tự nhiên trong văn phong Academic Task 1."}]', '{"taskResponse":"8.5/9.0 - Nêu bật được toàn bộ các số liệu mốc và điểm giao cắt năm 2018.","coherence":"8.0/9.0 - Từ nối (However, Conversely, In summary) được phân bố nhịp nhàng.","lexicalResource":"8.5/9.0 - Sử dụng các cụm từ đắt giá như ''photovoltaic technology'', ''unprecedented peak''.","grammar":"8.0/9.0 - Cấu trúc phức đa dạng, không có lỗi ngữ pháp cơ bản."}', '2026-10-20 08:00:00.000000');
INSERT INTO `ai_evaluations` (`id`, `student_answer_id`, `eval_type`, `overall_score`, `pronunciation_score`, `fluency_score`, `grammar_score`, `vocabulary_score`, `coherence_score`, `estimated_cefr`, `evaluation_engine`, `tokens_used`, `stt_transcript`, `corrected_text`, `mistakes_json`, `suggestions_json`, `created_at`) VALUES ('07070707-0000-0000-0000-000000000002', '06060606-0000-0000-0000-000000000002', 'SPEAKING', 86, 88, 84, 85, 87, 85, 'B2', 'TIER_1_SPEECHSUPER', 850, 'Today I would like to speak about an AI-powered code assistant that has radically transformed my development routine.', 'Today, I would like to speak about an AI-powered code assistant that has radically transformed my development routine.', '{"overallScore":86,"accuracyScore":88,"fluencyScore":84,"prosodyScore":85,"aiTierUsed":"TIER_1_SPEECHSUPER","words":[{"word":"Today","score":92,"status":"GOOD","phonemes":[{"ipa":"tə","score":90},{"ipa":"ˈdeɪ","score":94}]},{"word":"I","score":95,"status":"GOOD","phonemes":[{"ipa":"aɪ","score":95}]},{"word":"would","score":88,"status":"GOOD","phonemes":[{"ipa":"wʊd","score":88}]},{"word":"like","score":90,"status":"GOOD","phonemes":[{"ipa":"laɪk","score":90}]},{"word":"to","score":85,"status":"GOOD","phonemes":[{"ipa":"tuː","score":85}]},{"word":"speak","score":89,"status":"GOOD","phonemes":[{"ipa":"spiːk","score":89}]},{"word":"about","score":90,"status":"GOOD","phonemes":[{"ipa":"əˈbaʊt","score":90}]},{"word":"an","score":88,"status":"GOOD","phonemes":[{"ipa":"ən","score":88}]},{"word":"AI-powered","score":82,"status":"WARN","phonemes":[{"ipa":"eɪ.aɪ","score":85},{"ipa":"ˈpaʊ.ɚd","score":79}]},{"word":"code","score":91,"status":"GOOD","phonemes":[{"ipa":"koʊd","score":91}]},{"word":"assistant","score":85,"status":"GOOD","phonemes":[{"ipa":"əˈsɪs.tənt","score":85}]},{"word":"that","score":87,"status":"GOOD","phonemes":[{"ipa":"ðæt","score":87}]},{"word":"has","score":84,"status":"GOOD","phonemes":[{"ipa":"hæz","score":84}]},{"word":"radically","score":76,"status":"WARN","phonemes":[{"ipa":"ˈræd.ɪ.kəl.i","score":76}]},{"word":"transformed","score":88,"status":"GOOD","phonemes":[{"ipa":"trænsˈfɔːrmd","score":88}]},{"word":"my","score":93,"status":"GOOD","phonemes":[{"ipa":"maɪ","score":93}]},{"word":"development","score":87,"status":"GOOD","phonemes":[{"ipa":"dɪˈvel.əp.mənt","score":87}]},{"word":"routine","score":90,"status":"GOOD","phonemes":[{"ipa":"ruːˈtiːn","score":90}]}]}', '{"acousticNotes":"Pitch contour chuẩn 125Hz-220Hz. Âm /r/ trong ''radically'' cần cuộn lưỡi sâu hơn về vòm họng mềm.","recommendationVi":"Luyện phát âm nhấn trọng âm âm tiết 1 của ''radically'' để đạt độ tự nhiên bản xứ."}', '2026-10-20 08:00:00.000000');
INSERT INTO `ai_evaluations` (`id`, `student_answer_id`, `eval_type`, `overall_score`, `pronunciation_score`, `fluency_score`, `grammar_score`, `vocabulary_score`, `coherence_score`, `estimated_cefr`, `evaluation_engine`, `tokens_used`, `stt_transcript`, `corrected_text`, `mistakes_json`, `suggestions_json`, `created_at`) VALUES ('07070707-0000-0000-0000-000000000003', '06060606-0000-0000-0000-000000000003', 'SPEAKING', 92, 94, 91, 90, 90, 92, 'C1', 'TIER_3_FORMANT_PRAAT', 420, 'Continuous practice empowers learners to speak with unwavering confidence.', 'Continuous practice empowers learners to speak with unwavering confidence.', '{"overallScore":92,"accuracyScore":94,"fluencyScore":91,"prosodyScore":91,"aiTierUsed":"TIER_3_FORMANT_PRAAT","formants":{"f1AvgHz":520,"f2AvgHz":1840,"targetF1Hz":510,"targetF2Hz":1855,"formantAccuracyPercent":96.8},"words":[{"word":"Continuous","score":94,"status":"GOOD","phonemes":[{"ipa":"kənˈtɪn.ju.əs","score":94}]},{"word":"practice","score":95,"status":"GOOD","phonemes":[{"ipa":"ˈpræk.tɪs","score":95}]},{"word":"empowers","score":92,"status":"GOOD","phonemes":[{"ipa":"ɪmˈpaʊ.ɚz","score":92}]},{"word":"learners","score":93,"status":"GOOD","phonemes":[{"ipa":"ˈlɝː.nɚz","score":93}]},{"word":"to","score":96,"status":"GOOD","phonemes":[{"ipa":"tuː","score":96}]},{"word":"speak","score":94,"status":"GOOD","phonemes":[{"ipa":"spiːk","score":94}]},{"word":"with","score":92,"status":"GOOD","phonemes":[{"ipa":"wɪð","score":92}]},{"word":"unwavering","score":90,"status":"GOOD","phonemes":[{"ipa":"ʌnˈweɪ.vɚ.ɪŋ","score":90}]},{"word":"confidence","score":93,"status":"GOOD","phonemes":[{"ipa":"ˈkɑːn.fɪ.dəns","score":93}]}]}', '{"praatFeedback":"Độ lệch formants F1/F2 so với mẫu chuẩn Kokoro đạt 96.8% độ tương đồng. Xuất sắc!","intonation":"Ngữ điệu xuống giọng ở cuối câu hoàn hảo."}', '2026-10-20 08:00:00.000000');
